def canReturn(n, edges, s):
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
    seen = [False] * n
    stack = []
    for v in adj[s]:
        if not seen[v]:
            seen[v] = True
            stack.append(v)
    while stack:
        u = stack.pop()
        if u == s:
            return True
        for v in adj[u]:
            if not seen[v]:
                seen[v] = True
                stack.append(v)
    return False
